import com.sun.net.httpserver.*;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.*;

/** HTTP server and JSON API router. No framework or third-party library is used. */
public final class Server {
 private static final Path FRONT=Paths.get("frontend").toAbsolutePath().normalize();
 private static final int BODY_LIMIT=100*1024, RATE_LIMIT=readRate();
 private static final ConcurrentHashMap<String,Window> WINDOWS=new ConcurrentHashMap<>();
 private static final class Window{long start=System.currentTimeMillis();int count; synchronized boolean hit(){long n=System.currentTimeMillis();if(n-start>=60000){start=n;count=0;}return ++count<=RATE_LIMIT;}}
 private static int readRate(){try{return Math.max(1,Integer.parseInt(System.getenv().getOrDefault("RATE_LIMIT_PER_MIN","120")));}catch(Exception e){return 120;}}
 public static void main(String[]args)throws Exception{String envPort=System.getenv("PORT");int port=args.length>0?Integer.parseInt(args[0]):envPort==null||envPort.isBlank()?8080:Integer.parseInt(envPort);if(port<1||port>65535)throw new IllegalArgumentException("Port must be between 1 and 65535.");HttpServer s=HttpServer.create(new InetSocketAddress(port),0);s.createContext("/api",Server::api);s.createContext("/",Server::staticFile);s.setExecutor(Executors.newCachedThreadPool());s.start();System.out.println("Allin1Calc is running at http://localhost:"+port);}
 private static void headers(HttpExchange x){Headers h=x.getResponseHeaders();h.set("X-Content-Type-Options","nosniff");h.set("X-Frame-Options","DENY");h.set("Referrer-Policy","no-referrer");h.set("Content-Security-Policy","default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'");h.set("Cache-Control","no-store");}
 private static void send(HttpExchange x,int status,String type,byte[]b)throws IOException{headers(x);x.getResponseHeaders().set("Content-Type",type);x.sendResponseHeaders(status,b.length);try(OutputStream o=x.getResponseBody()){o.write(b);}}
 private static void json(HttpExchange x,int status,Object v)throws IOException{send(x,status,"application/json; charset=utf-8",Json.stringify(v).getBytes(StandardCharsets.UTF_8));}
 private static void api(HttpExchange x)throws IOException{try{String client=x.getRemoteAddress().getAddress().getHostAddress();if(!WINDOWS.computeIfAbsent(client,k->new Window()).hit()){json(x,429,Map.of("error","Request limit reached. Try again in a minute."));return;}
  String path=x.getRequestURI().getPath(),method=x.getRequestMethod();if(method.equals("OPTIONS")){json(x,405,Map.of("error","Method not allowed."));return;}
  if(method.equals("GET")){if(path.equals("/api/health")){json(x,200,Map.of("status","ok","version","1.0"));return;}if(path.equals("/api/units")){json(x,200,UnitConverter.units());return;}if(path.equals("/api/leap")){Map<String,String>q=query(x.getRequestURI().getRawQuery());if(q.containsKey("year")){int y=intQ(q.get("year"));json(x,200,Map.of("year",y,"leap",DateCalculator.leap(y)));return;}if(q.containsKey("from")&&q.containsKey("to")){int a=intQ(q.get("from")),b=intQ(q.get("to"));if(b<a||b-a>999)throw new IllegalArgumentException("Choose an ascending range of at most 1000 years.");List<Integer>ys=new ArrayList<>();for(int y=a;y<=b;y++)if(DateCalculator.leap(y))ys.add(y);json(x,200,Map.of("leapYears",ys,"count",ys.size()));return;}throw new IllegalArgumentException("Provide year or both from and to.");}json(x,404,Map.of("error","API route not found."));return;}
  if(!method.equals("POST")){json(x,405,Map.of("error","Method not allowed."));return;}Map<String,Object>m=Validator.object(Json.parse(readBody(x)));
  switch(path){case "/api/age":json(x,200,AgeCalculator.age(Validator.date(m,"dob"),m.containsKey("on")?Validator.date(m,"on"):LocalDate.now()));break;
   case "/api/age/difference":json(x,200,AgeCalculator.difference(Validator.date(m,"date1"),Validator.date(m,"date2")));break;
   case "/api/date/difference":json(x,200,DateCalculator.difference(Validator.date(m,"date1"),Validator.date(m,"date2")));break;
   case "/api/date/add":LocalDate result=DateCalculator.add(Validator.date(m,"date"),Validator.whole(m,"amount"),Validator.text(m,"unit"));json(x,200,Map.of("date",result.toString(),"weekday",result.getDayOfWeek().toString()));break;
   case "/api/date/workdays":json(x,200,Map.of("workdays",DateCalculator.workdays(Validator.date(m,"from"),Validator.date(m,"to"))));break;
   case "/api/time/calc":json(x,200,TimeCalculator.calc(Validator.text(m,"time1"),Validator.text(m,"time2"),m.getOrDefault("operation","add").toString()));break;
   case "/api/time/hours-worked":json(x,200,TimeCalculator.hoursWorked(Validator.text(m,"start"),Validator.text(m,"end")));break;
   case "/api/time/countdown":json(x,200,TimeCalculator.countdown(Validator.text(m,"target")));break;
   case "/api/convert":json(x,200,Map.of("result",UnitConverter.convert(Validator.number(m,"value"),Validator.text(m,"category"),Validator.text(m,"from"),Validator.text(m,"to"))));break;
   case "/api/attendance":json(x,200,AttendanceCalculator.calculate(Validator.whole(m,"total"),Validator.whole(m,"attended"),m.containsKey("target")?Validator.number(m,"target"):75));break;
   case "/api/percentage":json(x,200,Map.of("result",PercentageCalculator.calculate(Validator.text(m,"operation"),Validator.number(m,"a"),Validator.number(m,"b"))));break;
   case "/api/average":Object rawValues=m.get("values");if(rawValues==null||String.valueOf(rawValues).trim().isEmpty())throw new IllegalArgumentException("Enter at least one number.");String[]items=String.valueOf(rawValues).split(",");List<Double>nums=new ArrayList<>();if(items.length>1000)throw new IllegalArgumentException("Enter no more than 1000 numbers.");for(String item:items){String token=item.trim();if(token.length()>40)throw new IllegalArgumentException("Each number must be 40 characters or fewer.");try{double value=Double.parseDouble(token);if(!Double.isFinite(value))throw new NumberFormatException();nums.add(value);}catch(Exception e){throw new IllegalArgumentException("Enter finite numbers separated by commas.");}}json(x,200,AverageCalculator.calculate(nums));break;
   case "/api/cgpa":json(x,200,CgpaCalculator.convert(Validator.number(m,"cgpa"),m.containsKey("multiplier")?Validator.number(m,"multiplier"):9.5));break;
   default:json(x,404,Map.of("error","API route not found."));
  }
 }catch(IllegalArgumentException|ArithmeticException|DateTimeException e){json(x,400,Map.of("error",safeMessage(e)));}catch(Exception e){json(x,500,Map.of("error","A server error occurred. Please try again."));}finally{x.close();}}
 private static String safeMessage(Exception e){String m=e.getMessage();if(m==null||m.length()>200)return "Check the entered values and try again.";return m;}
 private static String readBody(HttpExchange x)throws IOException{byte[]buf=new byte[8192];ByteArrayOutputStream out=new ByteArrayOutputStream();int n,total=0;while((n=x.getRequestBody().read(buf))!=-1){total+=n;if(total>BODY_LIMIT)throw new IllegalArgumentException("Request body must be 100 KB or smaller.");out.write(buf,0,n);}return out.toString(StandardCharsets.UTF_8);}
 private static Map<String,String>query(String q){Map<String,String>m=new HashMap<>();if(q==null)return m;for(String part:q.split("&")){String[]kv=part.split("=",2);try{m.put(URLDecoder.decode(kv[0],"UTF-8"),kv.length>1?URLDecoder.decode(kv[1],"UTF-8"):"");}catch(Exception ignored){}}return m;}
 private static int intQ(String s){try{int n=Integer.parseInt(s);if(n<1||n>9999)throw new Exception();return n;}catch(Exception e){throw new IllegalArgumentException("Year must be from 1 to 9999.");}}
 private static void staticFile(HttpExchange x)throws IOException{try{if(!x.getRequestMethod().equals("GET")){send(x,405,"text/plain; charset=utf-8","Method not allowed".getBytes(StandardCharsets.UTF_8));return;}String raw=x.getRequestURI().getPath();if(raw.equals("/"))raw="/index.html";String decoded=URLDecoder.decode(raw,"UTF-8");Path file=FRONT.resolve(decoded.substring(1)).normalize();if(!file.startsWith(FRONT)||!Files.isRegularFile(file)){send(x,404,"text/plain; charset=utf-8","Not found".getBytes(StandardCharsets.UTF_8));return;}String type=Files.probeContentType(file);if(type==null)type="application/octet-stream";if(file.toString().endsWith(".js"))type="text/javascript; charset=utf-8";if(file.toString().endsWith(".css"))type="text/css; charset=utf-8";send(x,200,type,Files.readAllBytes(file));}finally{x.close();}}
}

